{"command":"python3 << 'EOF'
import zipfile

# Check which stops have invalid coordinates
with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as z:
    stops_content = z.read('stops.txt').decode('utf-8')

lines = stops_content.split('\n')
invalid_coords = []
for line in lines[1:]:
    if not line.strip():
        continue
    parts = line.split(',')
    if len(parts) >= 4:
        try:
            lat = float(parts[2])
            lon = float(parts[3])
            if lat < -90 or lat > 90 or lon < -180 or lon > 180:
                invalid_coords.append((parts[0], parts[2], parts[3]))
        except ValueError:
            pass

print(f"Invalid coordinates found: {len(invalid_coords)}")
for stop_id, lat, lon in invalid_coords:
    print(f"  {stop_id}: lat={lat}, lon={lon}")
EOF"}

